    10→export interface Team {
    11→  id: 'team1' | 'team2';
    12→  name: string;
    13→  color: string;
    14→  players: Player[];
    15→}
    16→
    17→export const DEFAULT_TEAM_COLORS = {
    18→  team1: '#0066cc', // Blue
    19→  team2: '#cc0000', // Red
    20→} as const;
    21→
    22→// Create initial players for a team
    23→export function createTeamPlayers(
    24→  teamId: 'team1' | 'team2',
    25→  color: string,
    26→  count: number = 18
    27→): Player[] {
    28→  const players: Player[] = [];
    29→  
    30→  for (let i = 0; i < count; i++) {
    31→    players.push({
    32→      id: `${teamId}-player-${i + 1}`,
    33→      teamId,
    34→      position: [0, 0, 0], // Will be positioned on field
    35→      rotation: 0,
    36→      color,
    37→      number: i + 1,
    38→    });
    39→  }
    40→  
    41→  return players;
    42→}
    43→

