    11→export function Toolbar({ canvas }: ToolbarProps) {
    12→  const resetPlayers = usePlayerStore((state) => state.resetPlayers);
    13→  const { setPresetView, resetCamera } = useCameraStore();
    14→  const { isRecording, toggleRecording } = useVideoRecorder(canvas);
    15→  const { saveCurrentScenario } = usePlaybook();
    16→  const [showSaveDialog, setShowSaveDialog] = useState(false);
    17→  const [playbookName, setPlaybookName] = useState('');
    18→  const [playbookDescription, setPlaybookDescription] = useState('');
    19→  
    20→  const handleSave = async () => {
    21→    if (!playbookName.trim()) {
    22→      alert('Please enter a name for the playbook');
    23→      return;
    24→    }
    25→    
    26→    try {
    27→      await saveCurrentScenario(playbookName, playbookDescription);
    28→      setShowSaveDialog(false);
    29→      setPlaybookName('');
    30→      setPlaybookDescription('');
