    33→      console.error('Error saving playbook:', error);
    34→      alert('Failed to save playbook. Please try again.');
    35→    }
    36→  };
    37→  
    38→  const handleRecordingToggle = () => {
    39→    if (!canvas) {
    40→      alert('Canvas not ready. Please wait a moment and try again.');
    41→      return;
    42→    }
    43→    toggleRecording();
