    50→        <button
    51→          onClick={() => setPresetView('top')}
    52→          className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 transition"
    53→        >
    54→          Top View
    55→        </button>
    56→        <button
    57→          onClick={() => setPresetView('sideline')}
    58→          className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 transition"
    59→        >
    60→          Sideline
    61→        </button>
    62→        <button
    63→          onClick={() => setPresetView('end-to-end')}
    64→          className="px-4 py-2 bg-blue-500 text-white rounded hover:bg-blue-600 transition"
    65→        >
    66→          End-to-End
    67→        </button>
    68→        
    69→        <div className="w-px bg-gray-300 mx-1" />
    70→        
    71→        {/* Player Controls */}
    72→        <button
    73→          onClick={resetPlayers}
    74→          className="px-4 py-2 bg-green-500 text-white rounded hover:bg-green-600 transition"
    75→        >
    76→          Reset Players
    77→        </button>
    78→        
    79→        <div className="w-px bg-gray-300 mx-1" />
    80→        
    81→        {/* Camera Controls */}
    82→        <button
    83→          onClick={resetCamera}
    84→          className="px-4 py-2 bg-purple-500 text-white rounded hover:bg-purple-600 transition"
    85→        >
    86→          Reset Camera
    87→        </button>
    88→        
    89→        <div className="w-px bg-gray-300 mx-1" />
    90→        
    91→        {/* Video Recording */}
    92→        <button
    93→          onClick={handleRecordingToggle}
    94→          className={`px-4 py-2 rounded transition ${
    95→            isRecording
    96→              ? 'bg-red-500 text-white hover:bg-red-600 animate-pulse'
    97→              : 'bg-gray-500 text-white hover:bg-gray-600'
    98→          }`}
    99→        >
   100→          {isRecording ? '⏹ Stop Recording' : '⏺ Start Recording'}
   101→        </button>
   102→        
   103→        <div className="w-px bg-gray-300 mx-1" />
   104→        
   105→        {/* Save Playbook */}
   106→        <button
   107→          onClick={() => setShowSaveDialog(true)}
   108→          className="px-4 py-2 bg-orange-500 text-white rounded hover:bg-orange-600 transition"
   109→        >
   110→          Save Playbook
   111→        </button>
   112→      </div>
   113→      
   114→      {/* Save Dialog */}
   115→      {showSaveDialog && (
   116→        <div className="bg-white/95 backdrop-blur-sm rounded-lg shadow-xl p-4 min-w-[300px]">
   117→          <h3 className="text-lg font-bold mb-3">Save Playbook</h3>
   118→          <div className="space-y-3">
   119→            <div>
   120→              <label className="block text-sm font-medium mb-1">Name *</label>
   121→              <input
   122→                type="text"
   123→                value={playbookName}
   124→                onChange={(e) => setPlaybookName(e.target.value)}
   125→                className="w-full px-3 py-2 border rounded"
   126→                placeholder="Enter playbook name"
   127→                autoFocus
   128→              />
   129→            </div>
   130→            <div>
   131→              <label className="block text-sm font-medium mb-1">Description</label>
   132→              <textarea
   133→                value={playbookDescription}
   134→                onChange={(e) => setPlaybookDescription(e.target.value)}
   135→                className="w-full px-3 py-2 border rounded"
   136→                placeholder="Enter description (optional)"
   137→                rows={3}
   138→              />
   139→            </div>
   140→            <div className="flex gap-2 justify-end">
   141→              <button
   142→                onClick={() => {
   143→                  setShowSaveDialog(false);
   144→                  setPlaybookName('');
