     1→import { useEffect, useRef } from 'react';
     2→import { useThree } from '@react-three/fiber';
     3→import { OrbitControls } from '@react-three/drei';
     4→import { useCameraStore } from '../../store/cameraStore';
     5→import * as THREE from 'three';
     6→
     7→export function CameraController() {
     8→  const { camera } = useThree();
     9→  const controlsRef = useRef<any>(null);
    10→  const { position, target, zoom } = useCameraStore();
    11→  
    12→  useEffect(() => {
    13→    // Update camera position when store changes
    14→    camera.position.set(...position);
    15→    camera.lookAt(...target);
    16→    camera.zoom = zoom;
    17→    camera.updateProjectionMatrix();
    18→    
    19→    if (controlsRef.current) {
    20→      controlsRef.current.target.set(...target);
    21→      controlsRef.current.update();
    22→    }
    23→  }, [camera, position, target, zoom]);
    24→  
    25→  return (
    26→    <OrbitControls
    27→      ref={controlsRef}
    28→      enableDamping
    29→      dampingFactor={0.05}
    30→      minDistance={10}
    31→      maxDistance={500}
    32→      minPolarAngle={0}
    33→      maxPolarAngle={Math.PI / 2}
    34→      enablePan
    35→      panSpeed={0.5}
    36→    />
    37→  );
    38→}
    39→

