     1→import { useAnnotationStore } from '../../store/annotationStore';
     2→import { Annotation } from '../../store/annotationStore';
     3→
     4→export function AnnotationLayer() {
     5→  const annotations = useAnnotationStore((state) => state.annotations);
     6→  
     7→  return (
     8→    <group>
     9→      {annotations.map((annotation) => (
    10→        <AnnotationRenderer key={annotation.id} annotation={annotation} />
    11→      ))}
    12→    </group>
    13→  );
    14→}
    15→
    16→function AnnotationRenderer({ annotation }: { annotation: Annotation }) {
    17→  if (annotation.points.length < 2) return null;
    18→  
    19→  switch (annotation.type) {
    20→    case 'line':
    21→    case 'arrow':
    22→      return <LineAnnotation annotation={annotation} />;
    23→    case 'circle':
    24→      return <CircleAnnotation annotation={annotation} />;
    25→    case 'rectangle':
    26→      return <RectangleAnnotation annotation={annotation} />;
    27→    case 'text':
    28→      return <TextAnnotation annotation={annotation} />;
    29→    default:
    30→      return null;
    31→  }
    32→}
    33→
    34→function LineAnnotation({ annotation }: { annotation: Annotation }) {
    35→  const points = annotation.points.map((p) => new Float32Array(p));
    36→  
    37→  return (
    38→    <line>
    39→      <bufferGeometry>
    40→        <bufferAttribute
    41→          attach="attributes-position"
    42→          count={points.length}
    43→          array={new Float32Array(points.flat())}
    44→          itemSize={3}
    45→        />
    46→      </bufferGeometry>
    47→      <lineBasicMaterial color={annotation.color} linewidth={annotation.thickness || 2} />
    48→    </line>
    49→  );
    50→}
    51→
    52→function CircleAnnotation({ annotation }: { annotation: Annotation }) {
    53→  if (annotation.points.length < 2) return null;
    54→  const center = annotation.points[0];
    55→  const radius = Math.sqrt(
    56→    Math.pow(annotation.points[1][0] - center[0], 2) +
    57→    Math.pow(annotation.points[1][2] - center[2], 2)
    58→  );
    59→  
    60→  return (
    61→    <mesh position={[center[0], 0.02, center[2]]} rotation={[-Math.PI / 2, 0, 0]}>
    62→      <ringGeometry args={[radius - 0.1, radius, 32]} />
    63→      <meshStandardMaterial color={annotation.color} />
    64→    </mesh>
    65→  );
    66→}
    67→
    68→function RectangleAnnotation({ annotation }: { annotation: Annotation }) {
    69→  if (annotation.points.length < 2) return null;
    70→  const [p1, p2] = annotation.points;
    71→  const width = Math.abs(p2[0] - p1[0]);
    72→  const height = Math.abs(p2[2] - p1[2]);
    73→  const centerX = (p1[0] + p2[0]) / 2;
    74→  const centerZ = (p1[2] + p2[2]) / 2;
    75→  
    76→  return (
    77→    <mesh position={[centerX, 0.02, centerZ]} rotation={[-Math.PI / 2, 0, 0]}>
    78→      <planeGeometry args={[width, height]} />
    79→      <meshStandardMaterial color={annotation.color} opacity={0.3} transparent />
    80→    </mesh>
    81→  );
    82→}
    83→
    84→function TextAnnotation({ annotation }: { annotation: Annotation }) {
    85→  if (!annotation.text || annotation.points.length < 1) return null;
    86→  const [x, y, z] = annotation.points[0];
    87→  
    88→  return (
    89→    <mesh position={[x, 1, z]}>
    90→      <planeGeometry args={[2, 0.5]} />
    91→      <meshStandardMaterial color="#ffffff" />
    92→    </mesh>
    93→  );
    94→}
