     1→import { useRef, useState, useEffect } from 'react';
     2→import { useFrame, useThree } from '@react-three/fiber';
     3→import { Mesh, Vector3, Plane } from 'three';
     4→import { Player } from '../../models/PlayerModel';
     5→import { usePlayerStore } from '../../store/playerStore';
     6→import { snapToField } from '../../utils/fieldGeometry';
     7→
     8→interface PlayerProps {
     9→  player: Player;
    10→}
    11→
    12→export function PlayerComponent({ player }: PlayerProps) {
    13→  const meshRef = useRef<Mesh>(null);
    14→  const groupRef = useRef<any>(null);
    15→  const [hovered, setHovered] = useState(false);
    16→  const [isDragging, setIsDragging] = useState(false);
    17→  const { selectedPlayerId, selectPlayer, updatePlayerPosition } = usePlayerStore();
    18→  const { camera, raycaster } = useThree();
    19→  const isSelected = selectedPlayerId === player.id;
    20→  
    21→  useFrame((state) => {
    22→    if (meshRef.current) {
    23→      meshRef.current.rotation.y = player.rotation;
    24→    }
    25→    
    26→    // Handle dragging with global pointer events
    27→    if (isDragging) {
    28→      raycaster.setFromCamera(state.pointer, camera);
    29→      const planeNormal = new Vector3(0, 1, 0);
    30→      const planePoint = new Vector3(0, 0, 0);
    31→      const intersection = raycaster.ray.intersectPlane(
    32→        new Plane(planeNormal, -planeNormal.dot(planePoint)),
    33→        new Vector3()
    34→      );
    35→      
    36→      if (intersection) {
    37→        const [x, z] = snapToField(intersection.x, intersection.z);
    38→        updatePlayerPosition(player.id, [x, 0, z]);
    39→      }
    40→    }
    41→  });
    42→  
    43→  const handleClick = (e: any) => {
    44→    e.stopPropagation();
    45→    selectPlayer(player.id);
    46→  };
    47→  
    48→  const handlePointerDown = (e: any) => {
    49→    e.stopPropagation();
    50→    selectPlayer(player.id);
    51→    setIsDragging(true);
    52→  };
    53→  
    54→  const handlePointerMove = (e: any) => {
    55→    // Movement is handled in useFrame for smoother dragging
    56→    if (isDragging) {
    57→      e.stopPropagation();
    58→    }
    59→  };
    60→  
    61→  const handlePointerUp = (e: any) => {
    62→    e.stopPropagation();
    63→    setIsDragging(false);
    64→  };
    65→  
    66→  return (
    67→    <group
    68→      ref={groupRef}
    69→      position={player.position}
    70→      onClick={handleClick}
    71→      onPointerDown={handlePointerDown}
    72→      onPointerMove={handlePointerMove}
    73→      onPointerUp={handlePointerUp}
    74→      onPointerOver={() => setHovered(true)}
    75→      onPointerOut={() => {
    76→        setHovered(false);
    77→        setIsDragging(false);
    78→      }}
    79→    >
    80→      {/* Player body - capsule shape */}
    81→      <mesh ref={meshRef} castShadow position={[0, 0.9, 0]}>
    82→        <capsuleGeometry args={[0.3, 1.2, 4, 8]} />
    83→        <meshStandardMaterial
    84→          color={isSelected ? '#ffff00' : hovered ? '#ffffff' : player.color}
    85→          emissive={isSelected ? '#ffff00' : player.color}
    86→          emissiveIntensity={isSelected ? 0.3 : 0.1}
    87→        />
    88→      </mesh>
    89→      
    90→      {/* Player number label */}
    91→      {player.number && (
    92→        <mesh position={[0, 1.5, 0.35]} rotation={[0, 0, 0]}>
    93→          <planeGeometry args={[0.4, 0.4]} />
    94→          <meshStandardMaterial color="#ffffff" />
    95→        </mesh>
    96→      )}
    97→      
    98→      {/* Selection indicator ring */}
    99→      {isSelected && (
   100→        <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.01, 0]}>
   101→          <ringGeometry args={[0.5, 0.6, 16]} />
   102→          <meshStandardMaterial color="#ffff00" emissive="#ffff00" emissiveIntensity={0.5} />
   103→        </mesh>
   104→      )}
   105→    </group>
   106→  );
